    /// <summary>Probability in millionths for a logit in hundredths (clamped to ±8.00).</summary>
    public static int Probability(int logitHundredths)
    {
        var z = Math.Clamp(logitHundredths, -MaxLogit, MaxLogit);
        return z >= 0 ? Table[z] : 1_000_000 - Table[-z];
    }
    /// <summary>The logit in hundredths of a strength difference: difference / scale, where the scale is rating points per
    /// logit unit in hundredths (700 = 7.00 points), rounded half to even.</summary>
    public static int Logit(long difference, int scaleHundredths) => (int)Math.Clamp(Numbers.Divide(difference * 10_000, scaleHundredths), -MaxLogit, MaxLogit);
    /// <summary>The probability (millionths) of winning a best-of-<paramref name="games"/> series when each game is won with
    /// probability <paramref name="game"/> (millionths), games independent. Exact integer arithmetic, rounded half to even
    /// once at the end.</summary>
    public static int Series(int game, int games)
    {
        var need = games / 2 + 1; var longest = 2 * need - 1;
        BigInteger p = game, q = 1_000_000 - game, one = 1_000_000, total = 0;
        // Sum over k games lost before the deciding win: C(need-1+k, k) p^need q^k, scaled to a common denominator.
        for (var k = 0; k < need; k++)
            total += Choose(need - 1 + k, k) * BigInteger.Pow(p, need) * BigInteger.Pow(q, k) * BigInteger.Pow(one, longest - need - k);
        var scale = BigInteger.Pow(one, longest);
        var quotient = BigInteger.DivRem(total * one, scale, out var remainder);
        if (remainder * 2 > scale || remainder * 2 == scale && !quotient.IsEven) quotient += 1;
        return (int)quotient;
    }
    private static BigInteger Choose(int n, int k)
    {
        BigInteger r = 1;
        for (var i = 1; i <= k; i++) r = r * (n - k + i) / i;
        return r;
    }
